const card = (n: Case['npc']) => ({ ...n, needs: new Set(n.needs), has: new Map(n.has), knows: new Set(n.knows), promises: new Set(n.promises), received: new Set(n.received), forbidden: new Set(n.forbidden) })
const S = (x: unknown) => new Set(x as string[])
const fx = (f: Record<string, unknown>): any => ({ ...f, requests: S(f.requests), offers: S(f.offers), refusals: S(f.refusals), handed: S(f.handed), wantsNow: S(f.wantsNow), forbiddenUsed: S(f.forbiddenUsed), mentions: S(f.mentions) })

describe('npcCheck accept() agrees with the verified Dafny Accept on every Witness lemma', () => {
    for (const c of CASES) {
        test(`${c.name}: Dafny says ${c.accept ? 'Accept' : '!Accept'}`, () => {
            expect(accept(card(c.npc), fx(c.facts)).length === 0).toBe(c.accept)
        })
    }
})
